    currentHero->z = object->z;
    currentHero->owner = static_cast<signed char>(placeholder->owner);
    currentHero->heroClass = sourceHero->heroClass;
    currentHero->patrolRadius = -1;
    currentHero->patrolX = hero::kPatrolNone;
